package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamClausesErrBank1 {
  private const val T = "Relative Clauses, Gerunds & Infinitives"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("The girl ___ won the all-island essay competition is in Grade 11.", "who", "which", "whom", "whose", "Use 'who' as the subject relative pronoun referring to a person."),
    q("This is the ancient temple ___ murals attract researchers worldwide.", "whose", "which", "whom", "who", "Use 'whose' to show possession for temples, people, or things."),
    q("The dictionary ___ you lent me yesterday was extremely helpful.", "which", "who", "whom", "where", "Use 'which' (or 'that') for objects/things in a relative clause."),
    q("The scientist ___ the committee honoured delivered an inspiring talk.", "whom", "which", "whose", "where", "'Whom' serves as the object relative pronoun referring to a person."),
    q("Kandy is the historic city ___ the Esala Perahera takes place annually.", "where", "which", "when", "whose", "Use 'where' to refer to a location where an action happens."),
    q("August is the month ___ many tourists visit the central highlands.", "when", "where", "which", "whom", "Use 'when' to refer to a period of time or date."),
    q("Can you explain the reason ___ the library closed early today?", "why", "which", "where", "whom", "'The reason why' explains cause cleanly in standard English."),
    q("The boy ___ bicycle was stolen reported the matter to the police.", "whose", "who", "whom", "which", "'Whose bicycle' expresses possession."),
    q("We visited the botanical garden ___ is famous for rare orchids.", "that", "who", "whom", "where", "'That' (or 'which') functions as the subject of the relative clause here ('is famous')."),
    q("The village ___ my grandfather was born lies near a lush paddy valley.", "where", "which", "who", "when", "'Where' replaces 'in which' when no preposition follows."),
    q("The hotel in ___ the delegates stayed overlooks Galle Face Green.", "which", "where", "that", "who", "After a preposition ('in'), use 'which' (not 'where' or 'that')."),
    q("The person to ___ I addressed the letter replied promptly.", "whom", "who", "that", "whose", "After a preposition ('to'), formal English requires 'whom'."),
    q("He is the kindest doctor ___ I have ever consulted.", "that", "whom", "which", "where", "After superlatives ('kindest'), 'that' is preferred as the relative pronoun."),
    q("Everything ___ happened during the storm was recorded in the log.", "that", "which", "who", "whom", "After indefinite pronouns like 'everything', 'all', or 'nothing', use 'that'."),
    q("Show me the exact photograph ___ was taken at Sigiriya summit.", "that", "who", "whom", "where", "'That' (or 'which') acts as subject referring to the photograph."),
    q("Mr. Perera, ___ teaches us English literature, is retiring this term.", "who", "that", "whom", "which", "Non-defining relative clauses (between commas) for people must use 'who', never 'that'."),
    q("Colombo, ___ is Sri Lanka's commercial hub, has a busy natural harbour.", "which", "that", "where", "who", "Non-defining relative clauses (after a comma) for places as subjects use 'which', never 'that'."),
    q("Do you remember the day ___ our school won the provincial trophy?", "when", "where", "which", "whose", "'When' modifies time nouns such as 'day'."),
    q("The stray puppy ___ we rescued last month has grown very playful.", "that", "who", "where", "whose", "'That' (or 'which') refers to an animal as object."),
    q("Students ___ complete the science project early earn bonus marks.", "who", "which", "whom", "whose", "'Students' is plural human subject, requiring 'who'."),
    q("The island ___ lies off the northern coast is reached by ferry.", "which", "where", "who", "when", "'Which' serves as the subject of 'lies', whereas 'where' cannot be a subject."),
    q("I met an artist ___ paintings capture rural village harvests.", "whose", "who", "whom", "which", "'Whose paintings' shows ownership."),
    q("That is the very book ___ all Grade 10 learners need for revision.", "that", "who", "where", "whom", "Emphatic 'the very + noun' pairs naturally with 'that'."),
    q("There is nobody here ___ disagrees with the class monitor's plan.", "who", "which", "whom", "whose", "Subject relative pronoun for 'nobody' is 'who' (or 'that')."),
    q("The hall ___ the prize giving was held was decorated with brass lamps.", "where", "which", "when", "who", "'Where' expresses the location of the event ('held')."),
    q("We thanked the volunteer ___ guided us safely down Adam's Peak.", "who", "whom", "which", "whose", "'Who' is the subject performing 'guided'."),
    q("Please return the stapler ___ was left on the staffroom desk.", "which", "where", "who", "whom", "'Which' is the subject of 'was left'."),
    q("The year 1948 was the milestone ___ Sri Lanka gained independence.", "when", "where", "which", "whose", "'When' links a year/time noun to a full clause."),
    q("I enjoy ___ detective stories before going to sleep.", "reading", "to read", "read", "reads", "The verb 'enjoy' is always followed by a gerund (-ing form)."),
    q("She suggested ___ a tree-planting campaign next Saturday.", "organizing", "to organize", "organize", "organized", "'Suggest' is followed by a gerund (-ing) or a 'that'-clause, never a to-infinitive."),
    q("We decided ___ our grandparents during the April holidays.", "to visit", "visiting", "visit", "visited", "'Decide' is followed by a to-infinitive ('to visit')."),
    q("He promised ___ the borrowed reference books by Monday morning.", "to return", "returning", "return", "returned", "'Promise' takes a to-infinitive ('to return')."),
    q("Would you mind ___ the classroom door because of the cold breeze?", "closing", "to close", "close", "closed", "'Would you mind' is always followed by a gerund ('closing')."),
    q("They avoided ___ through the flooded shortcut after heavy rain.", "walking", "to walk", "walk", "walked", "'Avoid' requires a gerund (-ing form)."),
    q("Malini hopes ___ medicine after completing her A/L studies.", "to study", "studying", "study", "studied", "'Hope' takes a to-infinitive ('to study')."),
    q("___ regularly in the morning keeps both body and mind active.", "Swimming", "Swim", "Swam", "Swims", "A gerund ('Swimming') acts cleanly as the subject of the sentence."),
    q("Stop ___ so much noise while the others are writing their test.", "making", "to make", "make", "made", "'Stop + -ing' means cease doing the activity."),
    q("On his way home, he stopped ___ fresh vegetables at the fair.", "to buy", "buying", "buy", "bought", "'Stop + to-infinitive' means pause one action in order to do another."),
    q("I clearly remember ___ the front gate before we boarded the bus.", "locking", "to lock", "lock", "locked", "'Remember + -ing' refers to recalling a past action already completed."),
    q("Please remember ___ your admission card to the examination hall tomorrow.", "to bring", "bringing", "bring", "brought", "'Remember + to-infinitive' reminds someone not to forget a future task."),
    q("He gave up ___ fast food after reading the health article.", "eating", "to eat", "eat", "ate", "Phrasal verbs ending in prepositions ('give up') take a gerund."),
    q("The prefect is responsible for ___ attendance every morning.", "marking", "to mark", "mark", "marked", "After any preposition ('for'), use a gerund (-ing form)."),
    q("We are looking forward to ___ the school band perform live.", "watching", "watch", "watched", "watches", "In 'look forward to', 'to' is a preposition, so it takes a gerund ('watching')."),
    q("She is used to ___ early even on chilly December mornings.", "waking", "wake", "waked", "wakes", "'Be used to' means accustomed to and takes a gerund ('waking')."),
    q("It is important ___ all instructions carefully before answering.", "to read", "reading", "read", "reads", "'It is + adjective' typically takes a to-infinitive ('to read')."),
    q("My father taught me ___ a bicycle when I was seven years old.", "to ride", "riding", "ride", "rode", "'Teach someone + to-infinitive' specifies the learned skill."),
    q("The strict warden made the boys ___ their dormitory before breakfast.", "tidy", "to tidy", "tidying", "tidied", "Causative 'make + object' takes a bare infinitive ('tidy' without 'to')."),
    q("Let the younger students ___ the front seats at the magic show.", "take", "to take", "taking", "taken", "'Let + object' always takes a bare infinitive ('take')."),
    q("I saw the kingfisher ___ swiftly into the clear garden pond.", "dive", "to dive", "dived", "dives", "Verbs of perception ('see/hear + object') take a bare infinitive for a complete action."),
    q("Instead of ___ time online, try sketching in a notebook.", "wasting", "to waste", "waste", "wasted", "'Instead of' ends in a preposition and must be followed by a gerund."),
    q("Before ___ the classroom, ensure all ceiling fans are switched off.", "leaving", "to leave", "leave", "left", "Preposition 'before' before a verb without a subject takes a gerund."),
    q("Without ___ his voice, the principal calmed the excited crowd.", "raising", "to raise", "raise", "raised", "Preposition 'without' requires a gerund ('raising')."),
    q("The athlete trained tirelessly in order ___ the national record.", "to break", "breaking", "break", "broke", "'In order + to-infinitive' expresses purpose."),
    q("This old wooden box is too heavy for one child ___.", "to lift", "lifting", "lift", "lifted", "'Too + adjective + to-infinitive' expresses impossibility."),
    q("Is the tea cool enough ___ safely right now?", "to drink", "drinking", "drink", "drank", "'Adjective + enough + to-infinitive' expresses sufficiency."),
    q("He pretended not ___ the warning bell after the interval.", "to hear", "hearing", "hear", "heard", "'Pretend' takes a to-infinitive ('not to hear')."),
    q("She offered ___ the heavy parcels for the elderly neighbour.", "to carry", "carrying", "carry", "carried", "'Offer' takes a to-infinitive ('to carry')."),
    q("Do you fancy ___ for an evening walk along the beach?", "going", "to go", "go", "went", "'Fancy' (meaning feel like) takes a gerund ('going')."),
    q("I regret ___ you that the outdoor trip is postponed due to rain.", "to inform", "informing", "inform", "informed", "'Regret + to inform/tell' introduces bad news politely."),
    q("He regrets ___ rude to his classmate during yesterday's debate.", "being", "to be", "be", "been", "'Regret + -ing' expresses sorrow about a past action."),
    q("The lawn needs ___ before the school sports meet next week.", "mowing", "to mow", "mow", "mowed", "'Need + -ing' carries a passive meaning ('needs to be mowed')."),
    q("We refused ___ part in any activity that harms wild animals.", "to take", "taking", "take", "taken", "'Refuse' takes a to-infinitive ('to take')."),
    q("Can you imagine ___ on a spaceship orbiting the moon?", "living", "to live", "live", "lived", "'Imagine' takes a gerund (-ing form)."),
    q("They managed ___ the steep hill just before sunset.", "to climb", "climbing", "climb", "climbed", "'Manage' (succeed in doing) takes a to-infinitive."),
    q("Keep ___ every day and your handwriting will soon improve.", "practising", "to practise", "practise", "practised", "'Keep + -ing' means continue an activity."),
    q("She agreed ___ the welcome speech at the English literary day.", "to deliver", "delivering", "deliver", "delivered", "'Agree' takes a to-infinitive ('to deliver')."),
    q("I cannot help ___ whenever I read that humorous short story.", "laughing", "to laugh", "laugh", "laughed", "Idiom 'cannot help + -ing' means cannot stop oneself from doing something."),
    q("It is no use ___ over spilled milk; let us fix the problem.", "crying", "to cry", "cry", "cried", "'It is no use + -ing' is a fixed gerund expression."),
    q("That gripping Sri Lankan film is definitely worth ___ twice.", "watching", "to watch", "watch", "watched", "'Worth + -ing' takes a gerund (never a to-infinitive)."),
    q("She had difficulty ___ the tiny village path in the thick mist.", "finding", "to find", "find", "found", "'Have difficulty/trouble + -ing' requires a gerund."),
    q("We heard the koel ___ sweetly from the tall mango tree.", "singing", "to sing", "sang", "sung", "'Hear + object + -ing' emphasizes an action in progress."),
    q("The coach encouraged the young runners ___ their best.", "to try", "trying", "try", "tried", "'Encourage + object + to-infinitive' is standard."),
    q("Our teacher advised us ___ neat margins on every answer sheet.", "to leave", "leaving", "leave", "left", "'Advise + object + to-infinitive' is standard (without object, 'advise + -ing')."),
    q("Doctors strongly advise ___ plenty of clean water in dry weather.", "drinking", "to drink", "drink", "drank", "Without an object, 'advise' takes a gerund ('drinking')."),
    q("The captain warned the sailors not ___ near the rocky reef.", "to steer", "steering", "steer", "steered", "'Warn + object + not to-infinitive' gives a negative warning."),
    q("She learned how ___ decorative origami cranes from coloured paper.", "to fold", "folding", "fold", "folded", "'Learn how + to-infinitive' describes acquiring a method."),
    q("___ excessive plastic bags pollutes waterways and blocks drains.", "Using", "Use", "Used", "Uses", "Gerund 'Using' acts as a singular noun subject matching 'pollutes'."),
    q("The hiker forgot ___ his raincoat, so he got soaked in the shower.", "to pack", "packing", "pack", "packed", "'Forget + to-infinitive' means fail to remember a required task."),
    q("I will never forget ___ the golden sunrise from Horton Plains.", "seeing", "to see", "see", "saw", "'Forget + -ing' refers to an unforgettable past memory."),
    q("The mechanic tried ___ the engine with a fresh battery.", "starting", "to start", "start", "started", "'Try + -ing' means test a method to see if it solves a problem."),
    q("Please try ___ your handwriting clearly so the examiner can read it.", "to write", "writing", "write", "wrote", "'Try + to-infinitive' means make an effort to achieve something."),
    q("___ by the heavy monsoon winds, several palm trees leaned low.", "Bent", "Bending", "To bend", "Bend", "A past participle clause ('Bent by...') shows passive cause."),
    q("___ up the narrow wooden stairs, they heard voices from the attic.", "Climbing", "Climbed", "To climb", "Climb", "A present participle clause ('Climbing up...') expresses simultaneous active action."),
    q("___ his homework early, Kasun went out to feed his pet pigeons.", "Having finished", "Having finish", "To finishing", "Finished", "Perfect participle ('Having finished') shows one action completed before the next."),
    q("The window ___ during last night's gale has already been replaced.", "broken", "breaking", "broke", "to break", "Reduced passive relative clause uses the past participle ('broken')."),
    q("The boy ___ in the blue track suit is our school sprint champion.", "running", "ran", "runs", "to run", "Reduced active relative clause uses the present participle ('running')."),
    q("He spends two hours every evening ___ English model essays.", "writing", "to write", "write", "wrote", "'Spend time + -ing' requires a gerund."),
    q("She had no choice but ___ patiently for the delayed express train.", "to wait", "waiting", "wait", "waited", "'Have no choice but + to-infinitive' is a fixed grammatical pattern."),
    q("We would rather ___ by train than sit in highway traffic.", "travel", "to travel", "travelling", "travelled", "'Would rather + bare infinitive' compares preferences cleanly."),
    q("You had better ___ an umbrella before dark clouds roll over.", "carry", "to carry", "carrying", "carried", "'Had better + bare infinitive' gives urgent advice."),
    q("Why not ___ the museum before the afternoon heat rises?", "visit", "to visit", "visiting", "visited", "'Why not + bare infinitive' makes a friendly suggestion."),
    q("The student ___ essay won first prize thanked his English teacher.", "whose", "who", "whom", "which", "'Whose essay' correctly links owner and noun."),
    q("Here is the exact spot ___ the ancient stone inscription was unearthed.", "where", "which", "when", "whom", "'Where' modifies 'spot' as the place of discovery."),
    q("Any parcel ___ exceeds five kilograms requires an extra stamp.", "that", "who", "whom", "where", "Relative pronoun 'that' (or 'which') refers to 'parcel' as subject."),
    q("The twins, neither of ___ spoke Sinhala fluently, learned fast at camp.", "whom", "who", "which", "whose", "After 'neither of', use the object relative pronoun 'whom' for people."),
    q("They bought three crates of mangoes, most of ___ were sweet and ripe.", "which", "that", "whom", "what", "After quantifiers + 'of' ('most of') in a non-defining clause for things, use 'which'."),
    q("Do you know ___ caused the sudden power cut across the street?", "what", "which", "that", "whom", "Nominal relative 'what' means 'the thing that' without an antecedent noun."),
    q("Wait here until I finish ___ the science lab equipment.", "cleaning", "to clean", "clean", "cleaned", "'Finish' must be followed by a gerund ('cleaning').")
  )
}
